  "is_atomic": true,
  "atomic_questions": [
    "Is the goal to minimize total cost (fixed setup costs plus variable production costs) while meeting all market demand, or is there a different objective such as maximizing profit or meeting a target production level?"
  ],
  "rationale": "The response asks for a single policy choice regarding the optimization objective, presenting mutually exclusive options within one sentence."
}

